interface LandmarkExplorerProps {
  onCityChange: (url: string) => void;
  language: 'ku' | 'ar';
}

const LandmarkExplorer: React.FC<LandmarkExplorerProps> = ({ onCityChange, language }) => {
  const [citiesData, setCitiesData] = useState<any>(initialCitiesData);
  const [selectedCity, setSelectedCity] = useState<string | null>(null);
  const [activeItem, setActiveItem] = useState<{ name: string; name_ar: string; info: string; info_ar: string } | null>(null);
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'neighborhoods' | 'districts' | 'tourism'>('neighborhoods');

  const isAdmin = auth.currentUser?.email === 'hedikurdaipro@admin.com';
  const [showAdmin, setShowAdmin] = useState<boolean>(false);
  const [targetCity, setTargetCity] = useState('slemani');
  const [targetType, setTargetType] = useState('neighborhoods');
  
  const [itemNameKu, setItemNameKu] = useState('');
  const [itemNameAr, setItemNameAr] = useState('');
  const [itemInfoKu, setItemInfoKu] = useState('');
  const [itemInfoAr, setItemInfoAr] = useState('');

  useEffect(() => {
    fetchLiveLandmarks();
  }, []);

  const fetchLiveLandmarks = async () => {
    try {
      const snapshot = await getDocs(query(collection(db, 'landmarks')));
      let deepCopy = JSON.parse(JSON.stringify(initialCitiesData));
      
      snapshot.forEach((doc) => {
        const data = doc.data();
        if(deepCopy[data.city] && deepCopy[data.city][data.type]) {
          deepCopy[data.city][data.type].push({ 
            name: data.name, name_ar: data.name_ar || data.name, 
            info: data.info, info_ar: data.info_ar || data.info 
          });
        }
      });
      setCitiesData(deepCopy);
    } catch(e) {
      setCitiesData(initialCitiesData);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if(!itemNameKu || !itemInfoKu) return alert(language === 'ku' ? "تکایە ناو و زانیاری پڕبکەرەوە" : "الرجاء ملء الاسم والمعلومات");

    try {
      await addDoc(collection(db, 'landmarks'), {
        city: targetCity, type: targetType, 
        name: itemNameKu, name_ar: itemNameAr || itemNameKu, 
        info: itemInfoKu, info_ar: itemInfoAr || itemInfoKu
      });
      alert(language === 'ku' ? "🎉 ناوچە نوێیەکە بە سەرکەوتوویی لە مۆبایلەوە زاخرا بۆ ناو داتابەیس!" : "🎉 تم حفظ المنطقة الجديدة بنجاح في قاعدة البيانات!");
      setShowAdmin(false); setItemNameKu(''); setItemNameAr(''); setItemInfoKu(''); setItemInfoAr('');
      fetchLiveLandmarks();
    } catch(err) { alert(language === 'ku' ? "هەڵە ڕوویدا" : "حدث خطأ"); }
  };

  const handleCityClick = (cityKey: string) => {
    setSelectedCity(cityKey);
    setSearchTerm('');
    setActiveTab('neighborhoods');
    onCityChange(citiesData[cityKey].image);
  };

  const getFilteredList = (list: { name: string; name_ar: string; info: string; info_ar: string }[]) => {
    return list ? list.filter(item => {
      const itemName = language === 'ku' ? item.name : (item.name_ar || item.name);
      return itemName.toLowerCase().includes(searchTerm.toLowerCase());
    }) : [];
  };

  return (
    <div className="p-4 md:p-8 max-w-6xl mx-auto text-right" dir="rtl">
      
      {isAdmin && (
        <div className="mb-6 text-center">
          <button type="button" onClick={() => setShowAdmin(!showAdmin)} className="px-4 py-2 bg-emerald-600 text-white font-black rounded-xl text-xs shadow-md">
            {showAdmin ? (language === 'ku' ? '✕ داخستنی پانێڵ' : '✕ إغلاق اللوحة') : (language === 'ku' ? '➕ زیادکردنی گەڕەک/قەزا بە مۆبایل' : '➕ إضافة حي/قضاء بالجوال')}
          </button>
        </div>
      )}

      {showAdmin && isAdmin && (
        <form onSubmit={handleSave} className="bg-slate-950 p-4 rounded-3xl border border-slate-800 space-y-3 mb-6 animate-in slide-in-from-top-4">
          <div className="grid grid-cols-1 sm:grid-cols-4 gap-3">
            <select value={targetCity} onChange={e=>setTargetCity(e.target.value)} className="p-2.5 bg-black text-white text-xs rounded-xl border border-slate-800 focus:outline-none">
              <option value="slemani">{language === 'ku' ? 'سلێمانی' : 'السليمانية'}</option>
              <option value="hawler">{language === 'ku' ? 'هەولێر' : 'أربيل'}</option>
              <option value="duhok">{language === 'ku' ? 'دهۆک' : 'دهوك'}</option>
              <option value="halabja">{language === 'ku' ? 'هەڵەبجە' : 'حلبجة'}</option>
              <option value="kirkuk">{language === 'ku' ? 'کەرکوک' : 'كركوك'}</option>
            </select>
            <select value={targetType} onChange={e=>setTargetType(e.target.value)} className="p-2.5 bg-black text-white text-xs rounded-xl border border-slate-800 focus:outline-none">
              <option value="neighborhoods">🏙️ {language === 'ku' ? 'گەڕەک' : 'حي'}</option>
              <option value="districts">🗺️ {language === 'ku' ? 'قەزا/ناحیە' : 'قضاء/ناحية'}</option>
              <option value="tourism">🌲 {language === 'ku' ? 'شوێنی گەشتیاری' : 'مكان سياحي'}</option>
            </select>
            <input type="text" placeholder={language === 'ku' ? 'ناو (کوردی)' : 'الاسم (كوردي)'} value={itemNameKu} onChange={e=>setItemNameKu(e.target.value)} className="p-2.5 bg-black text-white text-xs rounded-xl border border-slate-800 focus:outline-none" />
            <input type="text" placeholder={language === 'ku' ? 'ناو (عەرەبی)' : 'الاسم (عربي)'} value={itemNameAr} onChange={e=>setItemNameAr(e.target.value)} className="p-2.5 bg-black text-white text-xs rounded-xl border border-slate-800 focus:outline-none" />
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <textarea placeholder={language === 'ku' ? 'زانیاری (کوردی)...' : 'المعلومات (كوردي)...'} value={itemInfoKu} onChange={e=>setItemInfoKu(e.target.value)} className="w-full p-2.5 bg-black text-white text-xs rounded-xl border border-slate-800 h-20 focus:outline-none" />
            <textarea placeholder={language === 'ku' ? 'زانیاری (عەرەبی)...' : 'المعلومات (عربي)...'} value={itemInfoAr} onChange={e=>setItemInfoAr(e.target.value)} className="w-full p-2.5 bg-black text-white text-xs rounded-xl border border-slate-800 h-20 focus:outline-none" />
          </div>
          <button type="submit" className="w-full py-2.5 bg-yellow-500 text-black font-black text-xs rounded-xl shadow-lg">🚀 {language === 'ku' ? 'بڵاوکردنەوەی ڕاستەوخۆ' : 'نشر مباشر'}</button>
        </form>
      )}

      {!selectedCity ? (
        <div className="space-y-8 animate-in fade-in duration-500">
          <div className="w-full max-w-5xl mx-auto flex flex-col items-center gap-6">
            <h2 className="text-3xl sm:text-5xl font-black tracking-wide text-center text-transparent bg-clip-text bg-gradient-to-r from-red-600 via-yellow-500 to-green-600 drop-shadow-sm pb-2">
              {language === 'ku' ? 'نەخشەی کوردستانی گەورە' : 'خارطة كوردستان الكبرى'}
            </h2>
            <div className="w-full rounded-[2rem] overflow-hidden border border-slate-800/60 bg-slate-950/20 p-2 shadow-2xl relative group">
              <div className="absolute inset-0 bg-gradient-to-b from-indigo-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none"></div>
              <img src="/kurdistan2.jpg" alt="نەخشەی کوردستانی گەورە" className="w-full h-auto max-h-[650px] object-contain rounded-[1.7rem] opacity-95 group-hover:opacity-100 transition-all duration-500"/>
            </div>
          </div>

          <div className="flex flex-wrap justify-center items-center gap-6 sm:gap-8 max-w-5xl mx-auto pt-4 px-2">
            {Object.entries(citiesData).map(([key, city]: any) => (
              <button key={key} onClick={() => handleCityClick(key)} className="w-28 h-28 sm:w-44 sm:h-44 rounded-full bg-slate-900/60 border-2 border-slate-800 hover:border-indigo-500 flex flex-col items-center justify-center p-3 transition-all duration-300 group shadow-xl hover:shadow-indigo-500/10 hover:bg-slate-900 active:scale-[0.95] relative overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-tr from-indigo-600/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                <h3 className="text-base sm:text-2xl font-black text-white tracking-wide group-hover:text-indigo-400 transition-colors z-10">{language === 'ku' ? city.name : city.name_ar}</h3>
                <div className="w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full bg-slate-700 group-hover:bg-indigo-500 group-hover:shadow-[0_0_8px_rgba(99,102,241,1)] transition-all mt-2 sm:mt-3 z-10"></div>
              </button>
            ))}
          </div>

        </div>
      ) : (
        <div className="bg-slate-900/80 p-5 md:p-8 rounded-3xl border border-slate-700 animate-in fade-in zoom-in duration-300 space-y-8">
          <div className="flex justify-between items-center border-b border-slate-800 pb-4 flex-wrap gap-4">
            <button type="button" onClick={() => setSelectedCity(null)} className="text-indigo-400 font-black flex items-center gap-2 hover:translate-x-2 transition-transform text-xs sm:text-base">
              ← {language === 'ku' ? 'گەڕانەوە بۆ شارەکان' : 'العودة إلى المدن'}
            </button>
            
            <div className="w-full sm:w-80 relative">
              <input type="text" placeholder={language === 'ku' ? 'گەڕان...' : 'البحث...'} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-slate-950/60 border border-slate-700 hover:border-indigo-500 focus:border-indigo-500 rounded-full py-2.5 pr-6 pl-4 text-xs sm:text-sm text-slate-200 placeholder-slate-500 outline-none transition-all shadow-inner" />
            </div>
          </div>
          
          <div className="flex flex-col md:flex-row justify-between items-center md:items-start gap-8 border-b border-slate-800/40 pb-6">
            <div className="flex-1 space-y-4 text-right">
              <h2 className="text-3xl sm:text-4xl font-black text-white">{language === 'ku' ? citiesData[selectedCity].name : citiesData[selectedCity].name_ar}</h2>
              <p className="text-slate-300 leading-relaxed text-base sm:text-lg">{language === 'ku' ? citiesData[selectedCity].description : citiesData[selectedCity].description_ar}</p>
            </div>
            <div className="w-full md:w-auto shrink-0 flex justify-center">
              <img src={citiesData[selectedCity].image} alt={citiesData[selectedCity].name} className="w-56 h-56 sm:w-72 sm:h-72 object-cover rounded-3xl shadow-2xl border border-slate-700/50" />
            </div>
          </div>
          
          <div className="flex flex-wrap justify-center gap-3 sm:gap-6 pt-2">
            <button type="button" onClick={() => { setActiveTab('neighborhoods'); setSearchTerm(''); }} className={`px-5 py-3 sm:px-6 sm:py-4 rounded-full border-2 font-black text-xs sm:text-sm flex items-center gap-2 sm:gap-3 transition-all duration-300 active:scale-95 ${activeTab === 'neighborhoods' ? 'bg-indigo-600/20 border-indigo-500 text-indigo-400 shadow-[0_0_15px_rgba(99,102,241,0.15)]' : 'bg-slate-950/40 border-slate-800 text-slate-400 hover:border-slate-700'}`}>🏙️ {language === 'ku' ? 'گەڕەکەکانی شار' : 'أحياء المدينة'}</button>
            <button type="button" onClick={() => { setActiveTab('districts'); setSearchTerm(''); }} className={`px-5 py-3 sm:px-6 sm:py-4 rounded-full border-2 font-black text-xs sm:text-sm flex items-center gap-2 sm:gap-3 transition-all duration-300 active:scale-95 ${activeTab === 'districts' ? 'bg-emerald-600/20 border-emerald-500 text-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.15)]' : 'bg-slate-950/40 border-slate-800 text-slate-400 hover:border-slate-700'}`}>🗺️ {language === 'ku' ? 'قەزا و ناحییەکان' : 'الأقضية والنواحي'}</button>
            <button type="button" onClick={() => { setActiveTab('tourism'); setSearchTerm(''); }} className={`px-5 py-3 sm:px-6 sm:py-4 rounded-full border-2 font-black text-xs sm:text-sm flex items-center gap-2 sm:gap-3 transition-all duration-300 active:scale-95 ${activeTab === 'tourism' ? 'bg-amber-600/20 border-amber-500 text-amber-400 shadow-[0_0_15px_rgba(245,158,11,0.15)]' : 'bg-slate-950/40 border-slate-800 text-slate-400 hover:border-slate-700'}`}>🌲 {language === 'ku' ? 'ناوچە گەشتیارییەکان' : 'المناطق السياحية'}</button>
          </div>

          <div className="mt-8 pt-4 border-t border-slate-800/50">
            <div className="w-full max-h-[40vh] sm:max-h-80 overflow-y-auto flex flex-wrap gap-2.5 p-2 text-right scroll-smooth pr-2 [&::-webkit-scrollbar]:w-1.5 [&::-webkit-scrollbar-track]:bg-slate-900 [&::-webkit-scrollbar-thumb]:bg-slate-600 [&::-webkit-scrollbar-thumb]:rounded-full shadow-inner bg-slate-950/20 rounded-2xl">
              {getFilteredList(citiesData[selectedCity][activeTab]).map((item: any, i: number) => (
                <button type="button" key={i} onClick={() => setActiveItem(item)} className="px-4 py-2.5 bg-slate-800/80 rounded-full border border-slate-700 hover:border-indigo-400 hover:bg-slate-800 transition-all text-xs sm:text-sm font-bold text-slate-200 active:scale-95 shrink-0 shadow-md">
                  📍 {language === 'ku' ? item.name : (item.name_ar || item.name)}
                </button>
              ))}
              {getFilteredList(citiesData[selectedCity][activeTab]).length === 0 && (
                <p className="text-slate-500 text-sm italic py-2 w-full text-center">{language === 'ku' ? 'هیچ شوێنێک نەدۆزرایەوە...' : 'لم يتم العثور على أي مكان...'}</p>
              )}
            </div>
          </div>
        </div>
      )}

      {activeItem && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-md" onClick={() => setActiveItem(null)}></div>
          <div className="relative bg-slate-900 border border-slate-800 w-full max-w-2xl rounded-[2.5rem] p-6 md:p-8 shadow-2xl text-right animate-in zoom-in-95 duration-300 flex flex-col max-h-[85vh]">
            <div className="flex justify-between items-center pb-4 border-b border-slate-800 shrink-0">
              <h5 className="text-xl sm:text-2xl font-black text-indigo-400">{language === 'ku' ? activeItem.name : (activeItem.name_ar || activeItem.name)}</h5>
              <button type="button" onClick={() => setActiveItem(null)} className="w-9 h-9 sm:w-10 sm:h-10 rounded-full bg-slate-800 text-slate-400 hover:text-white flex items-center justify-center text-sm sm:text-lg font-bold shadow-md">✕</button>
            </div>
            <div className="mt-5 overflow-y-auto pr-2 text-slate-200 leading-7 sm:leading-8 text-sm sm:text-[16px] font-medium max-h-[50vh] [&::-webkit-scrollbar]:w-1.5 [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar-thumb]:bg-slate-700 [&::-webkit-scrollbar-thumb]:rounded-full">
              <p className="whitespace-pre-line text-justify">{language === 'ku' ? activeItem.info : (activeItem.info_ar || activeItem.info)}</p>
            </div>
            <div className="mt-6 pt-4 border-t border-slate-800 shrink-0 text-center">
              <button type="button" onClick={() => setActiveItem(null)} className="px-6 py-2.5 bg-indigo-600/20 border border-indigo-500/40 text-indigo-400 hover:bg-indigo-600 hover:text-white transition-all rounded-full font-black text-xs">{language === 'ku' ? 'داخستنی زانیاری' : 'إغلاق المعلومات'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default LandmarkExplorer;